contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _vader, address _usdv, address _vault) public payable {
        require(_vader != address(0));
        require(_usdv != address(0));
        require(_vault != address(0));

        c.init(_vader, _usdv, _vault); if (__ESBMC_reverted()) return;

        uint cool = c.coolOffPeriod(); if (__ESBMC_reverted()) return;

        assert(cool == 1);
    }

    receive() external payable {}
}

